/**
 * Server-side access to the synthetic OMOP CDM v5.4 demo dataset.
 *
 * A SEPARATE data asset from the trial corpus (lib/trialCorpus.ts reads
 * public/data/trial-corpus/): this store ships as columnar JSON under
 * public/data/omop-demo/, generated by pipeline/generate_omop_dataset.py, and
 * versions independently. Dates are integer day offsets from the manifest
 * epoch. Tables stay columnar in memory; consumers work through the typed
 * accessors and per-person indexes here rather than expanding rows to objects.
 *
 * See docs/omop-biostats-module.md for schema, provenance, and encoded signal.
 */

import fs from 'fs'
import path from 'path'

const OMOP_DIR = path.join(process.cwd(), 'public', 'data', 'omop-demo')

export interface Columnar {
  columns: string[]
  rows: (number | string)[][]
  rowCount: number
}

export interface OmopManifest {
  datasetId: string
  datasetVersion: string
  cdm: string
  epoch: string
  dataEnd: string
  generated: string
  seed: number
  synthetic: boolean
  personCount: number
  tables: Record<string, number>
  cohortCounts: Record<string, number>
  caveat: string
}

const cache = new Map<string, unknown>()

function readJson<T>(file: string): T {
  const key = `raw:${file}`
  if (!cache.has(key)) {
    cache.set(key, JSON.parse(fs.readFileSync(path.join(OMOP_DIR, file), 'utf-8')))
  }
  return cache.get(key) as T
}

export const omopManifest = () => readJson<OmopManifest>('manifest.json')

export type OmopTableName =
  | 'concept'
  | 'concept_ancestor'
  | 'person'
  | 'observation_period'
  | 'visit_occurrence'
  | 'condition_occurrence'
  | 'drug_exposure'
  | 'procedure_occurrence'
  | 'measurement'
  | 'death'
  | 'cohort'
  | 'cohort_definition'

export const omopTable = (name: OmopTableName) => readJson<Columnar>(`${name}.json`)

/** Column index by name; throws on a typo so schema drift fails loudly. */
export function colIdx(t: Columnar, column: string): number {
  const i = t.columns.indexOf(column)
  if (i === -1) throw new Error(`Unknown OMOP column "${column}" (have: ${t.columns.join(', ')})`)
  return i
}

/** Rows of a table grouped by one integer column (usually person_id). Cached. */
export function rowsBy(name: OmopTableName, column: string): Map<number, (number | string)[][]> {
  const key = `by:${name}:${column}`
  if (!cache.has(key)) {
    const t = omopTable(name)
    const ci = colIdx(t, column)
    const map = new Map<number, (number | string)[][]>()
    for (const row of t.rows) {
      const k = Number(row[ci])
      const list = map.get(k)
      if (list) list.push(row)
      else map.set(k, [row])
    }
    cache.set(key, map)
  }
  return cache.get(key) as Map<number, (number | string)[][]>
}

/** concept_id -> concept_name for labeling summaries. */
export function conceptNames(): Map<number, string> {
  const key = 'derived:conceptNames'
  if (!cache.has(key)) {
    const t = omopTable('concept')
    const id = colIdx(t, 'concept_id')
    const name = colIdx(t, 'concept_name')
    cache.set(key, new Map(t.rows.map((r) => [Number(r[id]), String(r[name])])))
  }
  return cache.get(key) as Map<number, string>
}

/** person_id -> death_day (only persons with a DEATH row). */
export function deathDays(): Map<number, number> {
  const key = 'derived:deathDays'
  if (!cache.has(key)) {
    const t = omopTable('death')
    const pid = colIdx(t, 'person_id')
    const d = colIdx(t, 'death_day')
    cache.set(key, new Map(t.rows.map((r) => [Number(r[pid]), Number(r[d])])))
  }
  return cache.get(key) as Map<number, number>
}

/** person_id -> [observation start day, end day]. */
export function observationPeriods(): Map<number, [number, number]> {
  const key = 'derived:obs'
  if (!cache.has(key)) {
    const t = omopTable('observation_period')
    const pid = colIdx(t, 'person_id')
    const s = colIdx(t, 'observation_period_start_day')
    const e = colIdx(t, 'observation_period_end_day')
    cache.set(
      key,
      new Map(t.rows.map((r) => [Number(r[pid]), [Number(r[s]), Number(r[e])] as [number, number]]))
    )
  }
  return cache.get(key) as Map<number, [number, number]>
}

export interface PersonRecord {
  gender_concept_id: number
  year_of_birth: number
  race_concept_id: number
  ethnicity_concept_id: number
  care_site_id: number
}

export function persons(): Map<number, PersonRecord> {
  const key = 'derived:persons'
  if (!cache.has(key)) {
    const t = omopTable('person')
    const [pid, g, y, r, e, cs] = [
      'person_id',
      'gender_concept_id',
      'year_of_birth',
      'race_concept_id',
      'ethnicity_concept_id',
      'care_site_id',
    ].map((c) => colIdx(t, c))
    cache.set(
      key,
      new Map(
        t.rows.map((row) => [
          Number(row[pid]),
          {
            gender_concept_id: Number(row[g]),
            year_of_birth: Number(row[y]),
            race_concept_id: Number(row[r]),
            ethnicity_concept_id: Number(row[e]),
            care_site_id: Number(row[cs]),
          },
        ])
      )
    )
  }
  return cache.get(key) as Map<number, PersonRecord>
}

const DAY_MS = 86400000

/** Integer day offset -> ISO date string, using the manifest epoch. */
export function dayToIso(dayOffset: number): string {
  const epoch = new Date(`${omopManifest().epoch}T00:00:00Z`).getTime()
  return new Date(epoch + dayOffset * DAY_MS).toISOString().slice(0, 10)
}

export const DAYS_PER_MONTH = 30.4375
